#include <iostream>
using namespace std;

int main() {
    int h, n;
    cin >> h >> n;

    int left = 1, right = (1 << h);
    int total = 0;
    int direction = 0;

    while (left < right) {
        int middle = (left + right) / 2;
        if (n <= middle) {
            if (direction == 0) {
                total += 1;
                direction = 1;
            } else {
                total += (1 << h);
            }
            right = middle;
        } else {
            if (direction == 1) {
                total += 1;
                direction = 0;
            } else {
                total += (1 << h);
            }
            left = middle + 1;
        }
        h -= 1;
    }

    cout << total << endl;
    return 0;
}
